def.body:
@ipv4 || (
  @ipv4 = (begin
    eth = ethernet
    if eth.ethertype == 2048
    else
      raise(Error.new("Ethertype is not IPv4 (0x0800), got 0x#{eth.ethertype.to_s(16)}"))
    end
    IPv4Header.new(eth.payload)
  end)
)

@tcp || (
  @tcp = (begin
    ip = ipv4
    if ip.protocol == 6
    else
      raise(Error.new("IP protocol is not TCP (6), got #{ip.protocol}"))
    end
    TCPHeader.new(ip.payload)
  end)
)

@udp || (
  @udp = (begin
    ip = ipv4
    if ip.protocol == 17
    else
      raise(Error.new("IP protocol is not UDP (17), got #{ip.protocol}"))
    end
    UDPHeader.new(ip.payload)
  end)
)

begin
  @handle.loop(count: count) do |packet|
    @dumper.dump(packet)
    if block.call(packet)
    else
      @handle.breakloop
      next
    end
  end
rescue BreakLoopError
end
